fn solve(n: i8, k: i8) -> Vec<i8> {
    // Work in a wider type to avoid any overflow issues during arithmetic.
    let n_i = n as i32;
    let k_i = k as i32;

    if k_i == 0 || k_i == n_i {
        return vec![0, 0];
    }

    let unselected = n_i - k_i;              // >= 0
    let max_val = unselected.min(2 * k_i);   // >= 0

    vec![1i8, max_val as i8]
}